import numpy as np

class PhaseTransitionMultimodalLandscape:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        """
        Evaluates the Phase Transition Multimodal Landscape.

        Parameters
        ----------
        x : array-like
            Input sample of dimension dim.

        Returns
        -------
        float
            The function value.
        """
        x = np.asarray(x, dtype=np.float64)
        if x.ndim == 0:
            x = np.array([x], dtype=np.float64)

        x0 = x[0]
        norm = np.linalg.norm(x)

        # Global minimum: Origin (0, ..., 0) with value 0
        # Three distinct optimization regimes based on x0 value

        # Regime 1: Left region (x0 < -1.0) - High multimodality
        if x0 < -1.0:
            # Rastrigin-like with high frequency oscillations
            frequency = 2.5
            amplitude = 12.0
            rastrigin = np.sum(
                x**2 - amplitude * np.cos(2.0 * np.pi * frequency * x) + amplitude
            )

            # Cross-dimensional interaction creates additional local minima
            if self.dim > 1:
                interaction = 0.0
                for i in range(self.dim - 1):
                    for j in range(i + 1, self.dim):
                        # Product-based interaction terms
                        interaction += 0.2 * np.sin(
                            3.0 * np.pi * x[i] * x[j] * (1.0 - 0.5 * np.exp(-norm/5.0))
                        )
            else:
                interaction = 0.0

            return float(rastrigin + interaction)

        # Regime 2: Transition zone (-1.0 <= x0 < 1.0) - Mixed characteristics
        elif x0 < 1.0:
            # Quadratic base with varying multimodal perturbations
            base = np.sum(x**2)

            # Multimodal perturbation that scales with distance from center
            perturbation_scale = 0.3 * (1.0 + 0.7 * (abs(x0) / 1.0))
            perturbation = perturbation_scale * np.sum(
                np.sin(2.0 * np.pi * (1.5 + 0.5 * (norm / 5.0)) * x)
            )

            # Anisotropic interaction term (different behavior per dimension)
            if self.dim > 1:
                anisotropic = 0.0
                for i in range(self.dim):
                    anisotropic += 0.15 * np.abs(
                        np.sin(2.0 * np.pi * x[i] * (1.0 + 0.3 * (i / self.dim)))
                    )
            else:
                anisotropic = 0.0

            return float(base + perturbation + anisotropic)

        # Regime 3: Right region (x0 >= 1.0) - Complex multimodal with traps
        else:
            # Base multimodal with multiple frequency layers
            freq_base = 1.5
            base_multimodal = np.sum(
                x**2 - 8.0 * np.cos(2.0 * np.pi * freq_base * x) + 8.0
            )

            # Secondary frequency creates more local minima
            secondary = 0.4 * np.sum(
                np.sin(4.0 * np.pi * (1.0 + 0.2 * norm) * x)
            )

            # Cross-dimensional product interactions (many saddle points and minima)
            if self.dim > 1:
                cross_interaction = 0.0
                for i in range(self.dim - 1):
                    for j in range(i + 1, self.dim):
                        cross_interaction += 0.18 * np.sin(
                            2.5 * np.pi * x[i] * x[j] * (0.8 + 0.4 * np.sin(0.5 * (i + j)))
                        )
            else:
                cross_interaction = 0.0

            # Multiple deceptive local minima clusters
            deceptive = 0.0
            cluster_centers = [
                np.array([2.5, 0, 0] + [0] * max(0, self.dim - 3)),
                np.array([-2.5, 0, 0] + [0] * max(0, self.dim - 3))
            ]
            for center in cluster_centers:
                dist = np.linalg.norm(x - center[:self.dim])
                deceptive += 0.25 * np.exp(-0.3 * (dist - 1.5)**2)

            return float(base_multimodal + secondary + cross_interaction + deceptive)

