class RadialRegimeShiftLandscape:
    def __init__(self, dim):
        self.dim = dim
        # Region boundaries for phase transitions
        self.core_boundary = 1.0
        self.intermediate_boundary = 3.0

    def f(self, x):
        x = np.asarray(x).astype(np.float64)
        r = np.linalg.norm(x)  # Radial distance from origin

        # Region-specific behaviors for non-homogeneity
        if r < self.core_boundary:
            # Smooth convex core region - easy optimization
            return self._core_regime(x, r)
        elif r < self.intermediate_boundary:
            # Oscillatory intermediate region with phase transitions
            return self._intermediate_regime(x, r)
        else:
            # Chaotic outer region with cross-dimensional coupling
            return self._outer_regime(x, r)

    def _core_regime(self, x, r):
        # Simple quadratic - smooth basin to protect global minimum
        return np.sum(x**2) + 0.05 * r**2 * np.sin(r**2)

    def _intermediate_regime(self, x, r):
        # Dimension-dependent phase shifts create local minima
        phase_factor = np.exp((r - self.core_boundary) / 1.5)
        oscillation = 0.0
        for i in range(self.dim):
            phase_shift = np.pi * i / self.dim
            oscillation += np.sin(phase_factor * x[i] + phase_shift) ** 2
        return np.sum(x**2) + 2.0 * oscillation * (1.0 + 0.5 * r)

    def _outer_regime(self, x, r):
        # Cross-dimensional interaction terms with exponential complexity
        interaction_strength = np.exp((r - self.intermediate_boundary) / 2.0)
        interaction_term = 0.0

        for i in range(self.dim):
            for j in range(i+1, self.dim):
                # Non-separable cross-dimensional coupling
                interaction_term += np.sin(x[i] * x[j] * interaction_strength) ** 2

        # Dimensional asymmetry
        asymmetry = 0.0
        for i in range(self.dim):
            asymmetry += abs(x[i]) ** (1.5 + 0.1 * i)

        return np.sum(x**2) + 5.0 * interaction_term + 0.8 * asymmetry

