class RadialPhaseRuptureLandscape:
    def __init__(self, dim):
        self.dim = dim
        # Region boundaries for phase transitions
        self.core_boundary = 1.0
        self.shell_boundary = 3.0

    def f(self, x):
        x = np.asarray(x).astype(np.float64)
        r = np.linalg.norm(x)  # Radial distance from origin

        # Region-specific behaviors for non-homogeneity
        if r < self.core_boundary:
            # Smooth convex core region - easy optimization
            return self._core_regime(x, r)
        else:
            # Rugged shell region with high-density multimodality
            return self._shell_regime(x, r)

    def _core_regime(self, x, r):
        # Simple quadratic - smooth basin to protect global minimum
        return np.sum(x**2)

    def _shell_regime(self, x, r):
        # Multi-frequency sinusoidal components
        fundamental_freq = 5.0 * np.pi
        harmonic_freq = 10.0 * np.pi
        fundamental = np.sum(np.sin(fundamental_freq * x))
        harmonic = np.sum(np.sin(harmonic_freq * x))

        # Cross-dimensional interaction terms
        interaction = 0.0
        for i in range(self.dim):
            for j in range(i+1, self.dim):
                interaction += np.sin(x[i] * x[j] * np.pi) ** 2

        # Distance-dependent modulation
        modulation = np.exp((r - self.core_boundary) / 1.5)

        # Combine components with increasing strength away from core
        return (np.sum(x**2) +
                modulation * (fundamental + harmonic) +
                2.0 * modulation * interaction)

