class FractalRegimeLandscape:
    def __init__(self, dim):
        self.dim = dim
        # Region boundaries for recursive fractal transitions
        self.core_boundary = 1.0
        self.shell_boundaries = [1.0, 2.0, 3.0, 4.0]
        self.max_recursion_depth = 3

    def f(self, x):
        x = np.asarray(x).astype(np.float64)
        r = np.linalg.norm(x)

        # Determine which shell we're in
        shell = 0
        for boundary in self.shell_boundaries:
            if r < boundary:
                break
            shell += 1

        # Apply recursive fractal pattern based on shell
        return self._recursive_fractal(x, r, shell, 0)

    def _recursive_fractal(self, x, r, shell, depth):
        if depth >= self.max_recursion_depth or shell >= len(self.shell_boundaries):
            return self._base_landscape(x, r, shell)

        # Recursive fractal pattern with increasing complexity
        base_value = self._base_landscape(x, r, shell)
        fractal_factor = 0.0

        # Dimension-dependent fractal patterns
        for i in range(self.dim):
            # Recursive sinusoidal modulation
            freq = 2.0 ** (depth + 1) * (1.0 + 0.1 * i)
            phase = np.pi * i / self.dim * (depth + 1)
            fractal_factor += np.sin(freq * x[i] + phase) ** 2

        # Cross-dimensional coupling in outer shells
        if shell > 1:
            interaction = 0.0
            for i in range(self.dim):
                for j in range(i+1, self.dim):
                    interaction += np.sin(x[i] * x[j] * (2.0 ** depth)) ** 2
            fractal_factor += 0.5 * interaction

        return base_value + 0.8 ** depth * fractal_factor + self._recursive_fractal(x, r, shell, depth + 1)

    def _base_landscape(self, x, r, shell):
        # Base landscape for each shell
        if shell == 0:  # Core region
            return np.sum(x**2) + 0.01 * r**2 * np.sin(r**2)
        elif shell == 1:  # First shell
            return np.sum(x**2) + 2.0 * np.sum(np.sin(3.0 * x) ** 2)
        elif shell == 2:  # Second shell
            phase_shifts = np.pi * np.arange(self.dim) / self.dim
            return np.sum(x**2) + 5.0 * np.sum(np.sin(5.0 * x + phase_shifts) ** 2)
        else:  # Outer shells
            interaction = 0.0
            for i in range(self.dim):
                for j in range(i+1, self.dim):
                    interaction += np.sin(x[i] * x[j] * (2.0 ** shell)) ** 2
            return np.sum(x**2) + 10.0 * interaction + 0.5 * np.sum(abs(x) ** (1.5 + 0.1 * shell))

