class QuantumEntanglementLandscape:
    def __init__(self, dim):
        self.dim = dim
        # Parameters for fractal regime transitions
        self.core_radius = 1.0
        self.fractal_radius = 2.5
        self.entanglement_radius = 4.0
        self.fractal_depth = 5
        self.entanglement_strength = 0.8

    def fractal_modulation(self, x, depth):
        """Apply fractal modulation for non-homogeneous behavior"""
        if depth <= 0:
            return 1.0
        r = np.linalg.norm(x)
        if r < self.core_radius:
            return 1.0
        elif r < self.fractal_radius:
            return 0.5 * (1 + np.sin(2 * np.pi * depth * r / self.fractal_radius))
        else:
            return self.fractal_modulation(x * 0.7, depth - 1) * 0.8

    def quantum_entanglement(self, x):
        """Apply quantum entanglement terms"""
        entanglement = 0.0
        for i in range(self.dim):
            for j in range(i + 1, self.dim):
                entanglement += np.sin(2 * np.pi * x[i] * x[j]) * self.entanglement_strength
        return entanglement

    def f(self, x):
        x = np.asarray(x)
        r = np.linalg.norm(x)

        # Core region: smooth quadratic basin
        if r < self.core_radius:
            return np.sum(x**2) * 0.1

        # Fractal transition zone
        elif r < self.fractal_radius:
            # Base quadratic term
            base = np.sum(x**2) * 0.1

            # Fractal modulation
            fractal_factor = self.fractal_modulation(x, self.fractal_depth)

            # Quantum entanglement terms
            entanglement = self.quantum_entanglement(x)

            return base + 5.0 * fractal_factor * np.sin(2 * np.pi * r) + 3.0 * entanglement**2

        # Entanglement outer shell
        else:
            # Base term
            base = np.sum(x**2) * 0.1

            # High-frequency oscillations with fractal scaling
            high_freq = 0.0
            for i in range(self.dim):
                freq = 10.0 * (1 + 0.2 * np.sin(0.5 * r))
                high_freq += np.sin(freq * x[i]) * 0.8

            # Cross-dimensional entanglement coupling
