            for i in range(self.dim):
                for j in range(i + 1, self.dim):
                    cross_entanglement += np.sin(2.0 * np.pi * x[i] * x[j]) * 0.5

            # Fractal-based phase shifts
            phase_shift = self.fractal_modulation(x, self.fractal_depth) * 0.5

            return base + 10.0 * high_freq**2 + 8.0 * cross_entanglement**2 + 15.0 * np.sin(2 * np.pi * r + phase_shift)**2

import numpy as np

class PhasePartitionTessellationLandscape:
    def __init__(self, dim):
        self.dim = dim

        # Radial regime parameters
        self.radial_boundaries = np.array([0.3, 0.8, 1.5, 2.5, 4.0])
        self.num_radial_regimes = len(self.radial_boundaries) + 1

        # Angular sector partitioning (for dim >= 2)
        self.num_angular_sectors = 6
        self.angular_boundaries = np.linspace(0, 2*np.pi, self.num_angular_sectors + 1)

        # Hyperplane partitioning
        self.num_hyperplanes = 3
        self.hyperplane_weights = np.random.randn(self.num_hyperplanes, dim)
        self.hyperplane_biases = np.random.randn(self.num_hyperplanes)

        # Core quadratic parameters (global minimum at origin)
        self.core_scale = 1.0

        # Regime-specific parameters
        self.regime_params = {}
        self._initialize_regime_parameters()

    def _initialize_regime_parameters(self):
        """Initialize distinct parameters for each regime type"""
        regime_types = ['quadratic_core', 'smooth_quadratic', 'sinusoidal_coupled', 
                       'fractal_weierstrass', 'chaotic_high_freq', 'mixed_interference']

        for regime_type in regime_types:
            self.regime_params[regime_type] = {}

            if regime_type == 'quadratic_core':
                self.regime_params[regime_type] = {
                    'amplitude': 1.0,
                    'frequency': 0.0,
                    'noise_level': 0.0
                }
            elif regime_type == 'smooth_quadratic':
                self.regime_params[regime_type] = {
                    'amplitude': 0.8,
                    'frequency': 2.0,
                    'noise_level': 0.0
                }
            elif regime_type == 'sinusoidal_coupled':
                self.regime_params[regime_type] = {
                    'amplitude': 1.5,
                    'frequency': np.random.uniform(3.0, 8.0),
                    'noise_level': 0.1
                }
            elif regime_type == 'fractal_weierstrass':
                self.regime_params[regime_type] = {
                    'amplitude': 2.0,
                    'frequency': np.random.uniform(5.0, 15.0),
                    'noise_level': 0.3,
                    'fractal_dim': np.random.uniform(1.3, 1.8)
                }
            elif regime_type == 'chaotic_high_freq':
                self.regime_params[regime_type] = {
                    'amplitude': 2.5,
                    'frequency': np.random.uniform(10.0, 30.0),
                    'noise_level': 0.5
                }
            elif regime_type == 'mixed_interference':
                self.regime_params[regime_type] = {
                    'amplitude': 1.8,
                    'frequency': np.random.uniform(4.0, 12.0),
                    'noise_level': 0.2
                }

    def _get_radial_regime(self, distance):
        """Determine which radial regime based on distance from origin"""
        for i in range(len(self.radial_boundaries)):
            if distance <= self.radial_boundaries[i]:
                return i
        return self.num_radial_regimes - 1

    def _get_angular_sector(self, x):
        """Determine angular sector (for dim >= 2)"""
        if self.dim >= 2:
            angle = np.arctan2(x[1], x[0])
            if angle < 0:
                angle += 2*np.pi

            for i in range(len(self.angular_boundaries) - 1):
                if self.angular_boundaries[i] <= angle < self.angular_boundaries[i + 1]:
                    return i
            return self.num_angular_sectors - 1
        return 0

    def _get_hyperplane_signature(self, x):
        """Get binary signature from hyperplane evaluations"""
        hyperplane_values = self.hyperplane_weights @ x + self.hyperplane_biases
        signature = np.sum(hyperplane_values > 0)
        return int(signature)

    def _get_regime_type(self, radial_idx, angular_idx, hyperplane_sig):
        """Map region to a specific mathematical regime type"""
        # Create 6 distinct regime types based on combination
        regime_key = (radial_idx % 4) + (angular_idx % 2) + 2*(hyperplane_sig % 2)
        regime_types = ['quadratic_core', 'smooth_quadratic', 'sinusoidal_coupled', 
                       'fractal_weierstrass', 'chaotic_high_freq', 'mixed_interference']

        if radial_idx == 0:  # Core region
            return 'quadratic_core'
        else:
            return regime_types[regime_key % len(regime_types)]

    def _evaluate_regime(self, x, regime_type, params):
        """Evaluate the mathematical function for a specific regime"""
        if regime_type == 'quadratic_core':
            return self.core_scale * np.sum(x**2)

        elif regime_type == 'smooth_quadratic':
            return params['amplitude'] * np.sum(x**2) + 0.3 * np.sin(params['frequency'] * np.sqrt(np.sum(x**2)))

        elif regime_type == 'sinusoidal_coupled':
            freq = params['frequency']
            base = 0.0
            for i in range(self.dim):
                base += params['amplitude'] * np.sin(freq * x[i])
            for i in range(self.dim):
                for j in range(i+1, self.dim):
                    base += 0.2 * params['amplitude'] * np.sin(freq * x[i] * x[j])
            return base

        elif regime_type == 'fractal_weierstrass':
            a = params['amplitude']
            b = params['frequency']
            fractal_val = 0.0
            for k in range(1, 7):
                fractal_val += a ** (k-1) * np.cos(b ** (k-1) * np.sqrt(np.sum(x**2)))
            return fractal_val + params['noise_level'] * np.random.randn() * np.sum(np.abs(x))

        elif regime_type == 'chaotic_high_freq':
            freq = params['frequency']
            return params['amplitude'] * np.sum(np.sin(freq * x)**2) + \
                   0.5 * params['amplitude'] * np.sum(np.cos(2*freq * np.abs(x)))**2

        elif regime_type == 'mixed_interference':
            freq = params['frequency']
            interference = 0.0
            for i in range(self.dim):
                for j in range(i+1, min(i+3, self.dim)):
                    interference += params['amplitude'] * np.sin(freq * (x[i] + x[j])) * np.cos(freq * (x[i] - x[j]))
            return interference

    def _calculate_boundary_penalty(self, x, radial_idx, angular_idx, hyperplane_sig):
        """Add sharp penalty at regime boundaries to create discontinuous gradients"""
        distance = np.sqrt(np.sum(x**2))
        penalty = 0.0

        # Radial boundary penalties (sharp exponential walls)
        if radial_idx > 0:
            boundary = self.radial_boundaries[radial_idx - 1]
            if distance > 0:
                dist_to_boundary = abs(distance - boundary)
                if dist_to_boundary < 0.15:
                    penalty += 2.0 * np.exp(-15.0 * dist_to_boundary)

        # Hyperplane boundary penalties
        hyperplane_values = self.hyperplane_weights @ x + self.hyperplane_biases
        for hv in hyperplane_values:
            if abs(hv) < 0.5:
                penalty += 1.5 * np.exp(-10.0 * abs(hv))

        # Angular boundary penalties (for dim >= 2)
        if self.dim >= 2:
            angle = np.arctan2(x[1], x[0])
            if angle < 0:
                angle += 2*np.pi

            for bound in self.angular_boundaries[:-1]:
                dist_to_angular_boundary = min(abs(angle - bound), 2*np.pi - abs(angle - bound))
                if dist_to_angular_boundary < 0.3:
                    penalty += 1.2 * np.exp(-8.0 * dist_to_angular_boundary)

        return penalty

    def f(self, x):
        x = np.asarray(x, dtype=np.float64)
        n = len(x)

        # Ensure global bounds
        if n != self.dim:
            raise ValueError(f"Expected dimension {self.dim}, got {n}")

        # Calculate distance from origin
        distance = np.sqrt(np.sum(x**2))

        # 1. Global quadratic core (protects global minimum at origin)
        core_quadratic = self.core_scale * np.sum(x**2)

        # 2. Determine which regime we're in
        radial_idx = self._get_radial_regime(distance)
        angular_idx = self._get_angular_sector(x)
        hyperplane_sig = self._get_hyperplane_signature(x)
        regime_type = self._get_regime_type(radial_idx, angular_idx, hyperplane_sig)

        # 3. Get regime parameters
        params = self.regime_params[regime_type].copy()

        # 4. Evaluate the regime-specific function
        regime_value = self._evaluate_regime(x, regime_type, params)

        # 5. Apply regime-specific scaling based on distance (increases complexity outward)
        distance_scale = 1.0 + 0.5 * (distance / 4.0)
        regime_value *= distance_scale

        # 6. Add boundary penalties for sharp phase transitions
        boundary_penalty = self._calculate_boundary_penalty(x, radial_idx, angular_idx, hyperplane_sig)

        # 7. Add regime transition mixing (small overlap for smoothness at boundaries)
        transition_mix = 0.0
        if radial_idx > 0:
            prev_regime_type = self._get_regime_type(radial_idx - 1, angular_idx, hyperplane_sig)
            prev_params = self.regime_params[prev_regime_type].copy()
            prev_value = self._evaluate_regime(x, prev_regime_type, prev_params)
            prev_value *= distance_scale
            transition_mix = 0.05 * prev_value

        # 8. Combine all components
        total_value = core_quadratic + regime_value + boundary_penalty + transition_mix

        # 9. Apply regime-dependent weighting (outer regions more complex)
        regime_weight = 1.0 + 0.3 * radial_idx
        return core_quadratic + regime_weight * (regime_value + boundary_penalty + transition_mix)
